-- IAM approvals (maker-checker), event outbox and webhooks.
-- Seed rows are GENERATED by tools/gen-migrations.js from tools/catalogue.js.

CREATE TABLE approval_type (
    type_code           VARCHAR(40)  PRIMARY KEY,
    type_name           VARCHAR(120) NOT NULL,
    maker_permission    VARCHAR(60)  NOT NULL REFERENCES permission (permission_code),
    checker_permission  VARCHAR(60)  NOT NULL REFERENCES permission (permission_code),
    approvals_required  SMALLINT     NOT NULL DEFAULT 1 CHECK (approvals_required IN (1, 2)),
    pending_hours       INT          NOT NULL DEFAULT 72 CHECK (pending_hours > 0),
    consume_hours       INT          NOT NULL DEFAULT 24 CHECK (consume_hours > 0),
    callback_url        VARCHAR(300),
    active              BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CHECK (maker_permission <> checker_permission)
);

CREATE TABLE pending_action (
    action_id        UUID         PRIMARY KEY,
    type_code        VARCHAR(40)  NOT NULL REFERENCES approval_type (type_code),
    target_ref       VARCHAR(120) NOT NULL,
    summary          VARCHAR(300) NOT NULL,
    payload          TEXT         NOT NULL,
    payload_hash     CHAR(64)     NOT NULL,
    amount           NUMERIC(20,2),
    currency         VARCHAR(3),
    branch_code      VARCHAR(20),
    product_code     VARCHAR(40),
    status           VARCHAR(10)  NOT NULL
                     CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED', 'EXPIRED', 'CONSUMED')),
    maker            VARCHAR(60)  NOT NULL,
    submitted_by     VARCHAR(80)  NOT NULL,
    idempotency_key  VARCHAR(80),
    approvals_needed SMALLINT     NOT NULL,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at       TIMESTAMPTZ  NOT NULL,
    decided_at       TIMESTAMPTZ,
    consume_deadline TIMESTAMPTZ,
    consumed_at      TIMESTAMPTZ,
    consumed_by      VARCHAR(80),
    consumer_ref     VARCHAR(120),
    decision_comment VARCHAR(500),
    version          BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_pending_action_idem UNIQUE (type_code, idempotency_key),
    CHECK (amount IS NULL OR amount >= 0)
);
CREATE INDEX ix_pending_action_status ON pending_action (status, expires_at);
CREATE INDEX ix_pending_action_maker ON pending_action (maker, status);
CREATE INDEX ix_pending_action_type ON pending_action (type_code, status);
CREATE INDEX ix_pending_action_target ON pending_action (target_ref);

CREATE TABLE approval_decision (
    decision_id  BIGSERIAL PRIMARY KEY,
    action_id    UUID         NOT NULL REFERENCES pending_action (action_id),
    approver     VARCHAR(60)  NOT NULL,
    decision     VARCHAR(7)   NOT NULL CHECK (decision IN ('APPROVE', 'REJECT')),
    comment      VARCHAR(500),
    decided_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_approval_decision_once UNIQUE (action_id, approver)
);

CREATE TABLE event_outbox (
    event_id       BIGSERIAL PRIMARY KEY,
    event_type     VARCHAR(60)  NOT NULL,
    subject_key    VARCHAR(120) NOT NULL,
    payload        TEXT         NOT NULL,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    fanned_out_at  TIMESTAMPTZ
);
CREATE INDEX ix_event_outbox_pending ON event_outbox (event_id) WHERE fanned_out_at IS NULL;

CREATE TABLE webhook_subscription (
    sub_id       BIGSERIAL PRIMARY KEY,
    name         VARCHAR(80)  NOT NULL,
    url          VARCHAR(300) NOT NULL,
    event_types  VARCHAR(400) NOT NULL DEFAULT '*',
    secret_enc   TEXT         NOT NULL,
    active       BOOLEAN      NOT NULL DEFAULT TRUE,
    -- when set, this subscription is the callback of an approval type
    approval_type_code VARCHAR(40) REFERENCES approval_type (type_code),
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_by   VARCHAR(60)  NOT NULL,
    idempotency_key VARCHAR(80) UNIQUE
);

CREATE TABLE webhook_delivery (
    delivery_id      BIGSERIAL PRIMARY KEY,
    event_id         BIGINT       NOT NULL REFERENCES event_outbox (event_id),
    sub_id           BIGINT       NOT NULL REFERENCES webhook_subscription (sub_id),
    status           VARCHAR(10)  NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'DELIVERED', 'FAILED')),
    attempts         INT          NOT NULL DEFAULT 0,
    next_attempt_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_error       VARCHAR(300),
    delivered_at     TIMESTAMPTZ,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_webhook_delivery UNIQUE (event_id, sub_id)
);
CREATE INDEX ix_webhook_delivery_due ON webhook_delivery (next_attempt_at) WHERE status = 'PENDING';

